Given an array arr[] of integers and a range [low, high], find all the numbers within the range that are not present in the array. return the missing numbers in sorted order.Examples:  Input: arr[] = [10, 12, 11, 15], low = 10, high = 15Output: [13, 14]Explanation: Numbers 13 and 14 lie in the range [10, 15] but are not present in the array.Input: arr[] = [1, 4, 11, 51, 15], low = 50, high = 55Output: [50, 52, 53, 54, 55]Explanation: Numbers 50, 52, 53, 54 and 55 lie in the range [50, 55] but are not present in the array.Try It YourselfTable of Content[Naive Approach] Using Linear Search for Every Number - O((high - low + 1) * n) Time and O(1) Space[Better Approach] Using Sorting - O(n Log n) Time and O(1) Space[Expected Approach - 1] Using Hash Set - O(n + (high - low + 1)) Time and O(n) Space[Expected Approach - 2] Using Boolean Array - O(n + (high - low + 1)) Time and O(high - low + 1) Space[Naive Approach] Using Linear Search for Every Number - O((high - low + 1) * n) Time and O(1) SpaceThe idea is to iterate through every number in the range [low, high] and search for it in the array using a linear scan. If the number is not found, add it to the result.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> missingRange(vector<int> &arr, int low, int high)
{
    vector<int> res;

    // Check every number in the given range
    for (int num = low; num <= high; num++)
    {

        bool found = false;

        // Search current number in the array
        for (int x : arr)
        {
            if (x == num)
            {
                found = true;
                break;
            }
        }

        // If not present, add to result
        if (!found)
            res.push_back(num);
    }

    return res;
}

int main()
{

    vector<int> arr = {1, 4, 11, 51, 15};
    int low = 50, high = 55;

    vector<int> res = missingRange(arr, low, high);

    cout << "[";

    for (int i = 0; i < res.size(); i++)
    {
        cout << res[i];
        if (i != res.size() - 1)
            cout << ", ";
    }

    cout << "]";

    return 0;
}


