    #include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

vector<int> missingRange(vector<int> &arr, int low, int high)
{
    // Sort the array
    sort(arr.begin(), arr.end());

    vector<int> res;
    int i = 0;
    int n = arr.size();

    // Traverse all numbers in the range
    for (int x = low; x <= high; x++)
    {
        // Skip elements smaller than the current number
        while (i < n && arr[i] < x)
            i++;

        // If current number is missing, add it
        if (i == n || arr[i] != x)
            res.push_back(x);
    }

    return res;
}

