    #include <iostream>
#include <vector>
using namespace std;

vector<int> missingRange(vector<int> &arr, int low, int high)
{
    int m = high - low + 1;

    // Mark the numbers present in the range
    vector<bool> present(m, false);

    for (int x : arr)
    {
        if (x >= low && x <= high)
            present[x - low] = true;
    }

    vector<int> res;

    // Collect all missing numbers
    for (int i = 0; i < m; i++)
    {
        if (!present[i])
            res.push_back(low + i);
    }

    return res;
}

